import { CONTENT, format } from './contenido.js';

const GUIDE_FRAMES = {
  rest:'assets/epson_ia_mano_abajo.png',
  wave:'assets/epson_ia_mapache.png',
  blink:'assets/epson_ia_ojos_cerrados.png'
};
const GUIDE_REST_FALLBACK = 'data:image/png;base64,';
export function createGuideAnimation(image, {
  ImageType = Image,
  motion = window.matchMedia('(prefers-reduced-motion: reduce)'),
  page = document,
  schedule = setTimeout,
  cancel = clearTimeout,
  random = Math.random
} = {}) {
  const loaded = new Set();
  const timers = new Set();
  const preload = [];
  let active = false;
  let failed = false;
  let restFailed = false;
  function clearTimers() {
    for (const id of timers) cancel(id);
    timers.clear();
  }
  function later(callback, delay) {
    const id = schedule(() => { timers.delete(id); callback(); }, delay);
    timers.add(id);
  }
  function show(frame) {
    if (!loaded.has(frame)) return;
    image.hidden = false;
    if (image.getAttribute('src') !== GUIDE_FRAMES[frame]) image.src = GUIDE_FRAMES[frame];
  }
  function rest() {
    if (restFailed) {
      image.hidden = false;
      if (image.getAttribute('src') !== GUIDE_REST_FALLBACK) image.src = GUIDE_REST_FALLBACK;
    } else if (loaded.has('rest')) show('rest');
    else image.hidden = true;
  }
  function canMove() { return active && !failed && !motion.matches && !page.hidden; }
  function queueBlink() {
    if (!canMove()) return;
    later(() => {
      if (!canMove()) return;
      show('blink');
      later(() => { rest(); queueBlink(); }, 150);
    }, 3000 + random() * 2000);
  }
  function message() {
    active = true;
    clearTimers();
    rest();
    if (!canMove() || loaded.size !== 3) return;
    show('wave');
    later(() => { rest(); queueBlink(); }, 800);
  }
  function stop() { active = false; clearTimers(); rest(); }
  function degrade(frame) {
    failed = true;
    if (frame === 'rest') restFailed = true;
    clearTimers();
    rest();
  }
  for (const [frame, source] of Object.entries(GUIDE_FRAMES)) {
    const asset = new ImageType();
    preload.push(asset);
    asset.onload = () => {
      loaded.add(frame);
      if (frame === 'rest') rest();
      if (loaded.size === 3 && active) message();
    };
    asset.onerror = () => degrade(frame);
    asset.src = source;
  }
  image.addEventListener('error', () => {
    if (image.getAttribute('src') === GUIDE_FRAMES.rest) {
      loaded.delete('rest');
      degrade('rest');
    } else if (image.getAttribute('src') === GUIDE_REST_FALLBACK) {
      image.hidden = true;
    } else degrade();
  });
  const refresh = () => {
    clearTimers();
    rest();
    if (canMove() && loaded.size === 3) queueBlink();
  };
  motion.addEventListener('change', refresh);
  page.addEventListener('visibilitychange', refresh);
  return { message, stop };
}

export function createStoryController(game, { document, window, onStartMission }) {
  const { ui } = CONTENT[game.language];
  const { state, language } = game;
  const $ = id => document.getElementById(id);
  const guideAnimation = createGuideAnimation($('guide-image'), {
    ImageType:window.Image, motion:window.matchMedia('(prefers-reduced-motion: reduce)'), page:document
  });
  function renderWelcome() {
    $('welcome-progress').textContent = format(ui.welcomeProgress, { current:state.welcomeIndex + 1 });
    $('welcome-bar').value = state.welcomeIndex + 1;
    $('welcome-message').textContent = CONTENT[language].welcome[state.welcomeIndex];
    $('welcome-back').disabled = state.welcomeIndex === 0;
    $('welcome-next').textContent = state.welcomeIndex === 2 ? ui.startTrial : ui.next;
    guideAnimation.message();
  }
  function bindEvents() {
    $('start-day').addEventListener('click', () => {
      $('cover-screen').hidden = true;
      $('welcome-screen').hidden = false;
      renderWelcome();
      $('welcome-title').focus();
    });
    $('welcome-back').addEventListener('click', () => {
      if (state.welcomeIndex > 0) state.welcomeIndex -= 1;
      renderWelcome();
    });
    $('welcome-next').addEventListener('click', () => {
      if (state.welcomeIndex < 2) { state.welcomeIndex += 1; renderWelcome(); return; }
      guideAnimation.stop();
      $('welcome-screen').hidden = true;
      document.body.classList.add('in-game');
      onStartMission();
    });
  }
  return { renderWelcome, guideAnimation, bindEvents };
}
